SET session_replication_role = DEFAULT;

-- Step 3: Reset sequences
SELECT setval('users_id_seq', COALESCE((SELECT MAX(id) FROM users), 1), true);
SELECT setval('wallets_id_seq', COALESCE((SELECT MAX(id) FROM wallets), 1), true);
SELECT setval('bots_id_seq', COALESCE((SELECT MAX(id) FROM bots), 1), true);
SELECT setval('transactions_id_seq', COALESCE((SELECT MAX(id) FROM transactions), 1), true);
SELECT setval('commissions_id_seq', COALESCE((SELECT MAX(id) FROM commissions), 1), true);
SELECT setval('game_configs_id_seq', COALESCE((SELECT MAX(id) FROM game_configs), 1), true);
SELECT setval('bot_texts_id_seq', COALESCE((SELECT MAX(id) FROM bot_texts), 1), true);
SELECT setval('rank_titles_id_seq', COALESCE((SELECT MAX(id) FROM rank_titles), 1), true);

SELECT 'Migration complete! Users: ' || count(*)::text FROM users;
SELECT 'Wallets: ' || count(*)::text FROM wallets;
SELECT 'Bots: ' || count(*)::text FROM bots;
